import React from 'react';
import { graphql } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';

const BookHero = styled.section`
  min-height: 60vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(
      circle at 70% 30%,
      rgba(0, 78, 137, 0.15) 0%,
      transparent 50%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: ${props => props.theme.space[10]};
  align-items: center;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    grid-template-columns: 1fr;
    gap: ${props => props.theme.space[6]};
  }
`;

const BookCover = styled.img`
  width: 200px;
  height: auto;
  border-radius: ${props => props.theme.radii.lg};
  box-shadow: ${props => props.theme.shadows['2xl']};
  transition: transform 0.3s ease;

  &:hover {
    transform: scale(1.05);
  }

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    width: 150px;
    margin: 0 auto;
  }
`;

const BookInfo = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${props => props.theme.space[4]};
`;

const BookCategory = styled.span`
  display: inline-block;
  font-size: ${props => props.theme.typography.fontSizes.sm};
  font-weight: ${props => props.theme.typography.fontWeights.semibold};
  color: ${props => props.theme.colors.secondary};
  text-transform: uppercase;
  letter-spacing: ${props => props.theme.typography.letterSpacings.wider};
`;

const BookTitle = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['5xl']};
  margin-bottom: ${props => props.theme.space[3]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.secondary} 0%,
    ${props => props.theme.colors.primary} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['3xl']};
  }
`;

const BookDescription = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.xl};
  color: var(--color-text-secondary);
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
  margin-top: ${props => props.theme.space[4]};
`;

const ReviewContent = styled.article`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[12]} ${props => props.theme.space[6]};

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
    margin-top: ${props => props.theme.space[16]};
    margin-bottom: ${props => props.theme.space[6]};
    color: var(--color-text);
  }

  h3 {
    font-size: ${props => props.theme.typography.fontSizes['2xl']};
    margin-top: ${props => props.theme.space[10]};
    margin-bottom: ${props => props.theme.space[4]};
    color: var(--color-text);
  }

  h4 {
    font-size: ${props => props.theme.typography.fontSizes.xl};
    margin-top: ${props => props.theme.space[8]};
    margin-bottom: ${props => props.theme.space[3]};
    color: var(--color-text);
  }

  p {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
  }

  img {
    width: 100%;
    border-radius: ${props => props.theme.radii.xl};
    margin: ${props => props.theme.space[8]} 0;
    box-shadow: ${props => props.theme.shadows.xl};
  }

  ul, ol {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
    padding-left: ${props => props.theme.space[8]};
  }

  li {
    margin-bottom: ${props => props.theme.space[3]};
  }

  blockquote {
    border-left: 4px solid ${props => props.theme.colors.secondary};
    padding-left: ${props => props.theme.space[6]};
    margin: ${props => props.theme.space[8]} 0;
    font-style: italic;
    color: var(--color-text-secondary);
    font-size: ${props => props.theme.typography.fontSizes.xl};
    background: rgba(0, 78, 137, 0.05);
    padding: ${props => props.theme.space[6]};
    border-radius: ${props => props.theme.radii.lg};
  }

  code {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[1]} ${props => props.theme.space[2]};
    border-radius: ${props => props.theme.radii.sm};
    font-family: ${props => props.theme.typography.fonts.mono};
    font-size: 0.9em;
  }

  pre {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[6]};
    border-radius: ${props => props.theme.radii.lg};
    overflow-x: auto;
    margin: ${props => props.theme.space[8]} 0;

    code {
      background: none;
      padding: 0;
    }
  }

  hr {
    margin: ${props => props.theme.space[12]} 0;
    border: none;
    height: 1px;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--color-border) 50%,
      transparent 100%
    );
  }
`;

function BookReview({ data }) {
  const { markdownRemark: book } = data;
  const { t } = useTranslation();

  if (!book) {
    return <div>Book review not found</div>;
  }

  const { frontmatter, html } = book;

  return (
    <Layout
      title={frontmatter.title}
      description={frontmatter.description}
      image={frontmatter.img}
      path={`/books/${frontmatter.page_id}`}
    >
      <BookHero>
        <HeroContent>
          {frontmatter.img && (
            <BookCover
              src={frontmatter.img}
              alt={frontmatter.title}
              loading="eager"
            />
          )}
          <BookInfo>
            <BookCategory>
              {t('books.review', 'Book Review')}
            </BookCategory>
            <BookTitle>{frontmatter.title}</BookTitle>
            {frontmatter.description && (
              <BookDescription>{frontmatter.description}</BookDescription>
            )}
          </BookInfo>
        </HeroContent>
      </BookHero>

      <ReviewContent>
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </ReviewContent>
    </Layout>
  );
}

export default BookReview;

export const query = graphql`
  query BookByIdAndLanguage($id: String!, $language: String!) {
    markdownRemark(id: { eq: $id }) {
      id
      html
      frontmatter {
        page_id
        title
        description
        img
        category
        lang
      }
    }
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
